UPDATE public.paid_aragon_awards a SET enrichment = x.enrichment, province = x.province, dataset_date = '2026-11-20' FROM jsonb_to_recordset($paip$[{"import_key":"59ecef5fe38bf993c7089d8d","enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[],"related_company_operations":[{"operation_code":"2021071","year":2021,"line":"TDI-FEDER (antecedente)","beneficiary":"LEVITEC SISTEMAS, S.L.L.","feder_beneficiary_id":"ES51DM56","operation_name":"LEVITEC SISTEMAS, S.L.","description":"\"Diseño de un mantenimiento preventivo inteligente. Mejora del rendimiento de las instalaciones de autoconsumo y gestión de instalaciones aisladas.\"","start_date":"01/01/2020","end_date":"31/12/2020","feder_operation_cost":24000.0,"eu_cofinancing_percent":50.0,"province":"Huesca","municipality":"Huesca","municipality_code":"22125","intervention":"001 Inversión productiva genérica en pequeñas y medianas –empresas («PYME»)","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=280","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":280,"source_updated":"2025-05-29"},{"operation_code":"D2021105","year":2021,"line":"IDIS-REACT","beneficiary":"LEVITEC SISTEMAS, S.L.L.","feder_beneficiary_id":"ES51DM56","operation_name":"LEVITEC SISTEMAS, S.L.","description":"\"LEVITEC alcanzará en el ejercicio 2021 los 70 millones de facturación, duplicando las cifras del año pasado, gracias al desarrollo de tres nuevas líneas de negocio innovadoras: Energías Renovables, Autoconsumos y Mantenimiento, apoyando la transición ecológica hacia un futuro con energías limpias. Con este objetivo de diversificación, a finales de 2020 se contrata un servicio de consultoría de planificación para la búsqueda de alianzas estratégicas. Este servicio culmina con la formalización de un acuerdo de colaboración con el grupo FORESTALIA, empresa aragonesa de éxito líder en su sector, para el desarrollo de una cartera de 600 MW de potencia eólica y solar fotovoltaica en Aragón. Además de ser el promotor de estos proyectos, LEVITEC se encargará de la ejecución y puesta en marcha. Como complemento a esta nueva línea de negocio, compatible con la especialización en la ejecución de instalaciones eléctricas, que es la actividad tradicional de LEVITEC, la compañía crea un nuevo departamento de Autoconsumos, para ejecutar en proyectos públicos, residenciales, educacionales e industriales. LEVITEC también potencia el departamento de mantenimiento de instalaciones, para dar continuidad en el servicio a nuestros clientes. En 2020, LEVITEC también decide invertir en desarrollo de la organización y para ello contrata los servicios de asesoramiento externo de un coach o mentor, que ha trabajado en la alineación de los objetivos con los directivos y los distintos departamentos. El proyecto se ha materializado con la realización de distintas inversiones en las sedes de Zaragoza y Huesca. \"","start_date":"01/02/2020","end_date":"31/07/2021","feder_operation_cost":3294.0,"eu_cofinancing_percent":100.0,"province":"Huesca","municipality":"Huesca","municipality_code":"22125","intervention":"004 Inversión productiva relativas a la cooperación entre grandes empresas y PYME para desarrollar productos y servicios en tecnologías de la información y las comunicaciones (TIC), comercio electrónico y mayor demanda de TIC.","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=527","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":527,"source_updated":"2025-05-29"},{"operation_code":"V2021062","year":2021,"line":"IDIS-REACT","beneficiary":"LEVITEC SISTEMAS, S.L.L.","feder_beneficiary_id":"ES51DM56","operation_name":"LEVITEC SISTEMAS, S.L.","description":"\"LEVITEC alcanzará en el ejercicio 2021 los 70 millones de facturación, duplicando las cifras del año pasado, gracias al desarrollo de tres nuevas líneas de negocio innovadoras: Energías Renovables, Autoconsumos y Mantenimiento, apoyando la transición ecológica hacia un futuro con energías limpias. Con este objetivo de diversificación, a finales de 2020 se contrata un servicio de consultoría de planificación para la búsqueda de alianzas estratégicas. Este servicio culmina con la formalización de un acuerdo de colaboración con el grupo FORESTALIA, empresa aragonesa de éxito líder en su sector, para el desarrollo de una cartera de 600 MW de potencia eólica y solar fotovoltaica en Aragón. Además de ser el promotor de estos proyectos, LEVITEC se encargará de la ejecución y puesta en marcha. Como complemento a esta nueva línea de negocio, compatible con la especialización en la ejecución de instalaciones eléctricas, que es la actividad tradicional de LEVITEC, la compañía crea un nuevo departamento de Autoconsumos, para ejecutar en proyectos públicos, residenciales, educacionales e industriales. LEVITEC también potencia el departamento de mantenimiento de instalaciones, para dar continuidad en el servicio a nuestros clientes. En 2020, LEVITEC también decide invertir en desarrollo de la organización y para ello contrata los servicios de asesoramiento externo de un coach o mentor, que ha trabajado en la alineación de los objetivos con los directivos y los distintos departamentos. El proyecto se ha materializado con la realización de distintas inversiones en las sedes de Zaragoza y Huesca. \"","start_date":"01/02/2020","end_date":"31/07/2021","feder_operation_cost":139941.0,"eu_cofinancing_percent":100.0,"province":"Huesca","municipality":"Huesca","municipality_code":"22125","intervention":"071 Desarrollo y promoción de empresas especializadas en prestación de servicios que contribuyen a la economía con bajas emisiones de carbono y a la resistencia al cambio climático (incluyendo el apoyo a dichos servicios)","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=1127","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":1127,"source_updated":"2025-05-29"},{"operation_code":"V2022061","year":2022,"line":"IDIS-REACT","beneficiary":"LEVITEC SISTEMAS, S.L.L.","feder_beneficiary_id":"ES51DM56","operation_name":"LEVITEC SISTEMAS, S.L.","description":"El objetivo general de este proyecto es impulsar el crecimiento del departamento de autoconsumo de LEVITEC mediante la investigación y el desarrollo de algoritmos predictivos capaces de anticipar fallos y analizar datos en las instalaciones de autoconsumo y de puntos de recarga, con la ayuda de una la plataforma de monitorizacion.","start_date":"01/02/2021","end_date":"31/08/2022","feder_operation_cost":4463.0,"eu_cofinancing_percent":100.0,"province":"Huesca","municipality":"Huesca","municipality_code":"22125","intervention":"071 Desarrollo y promoción de empresas especializadas en prestación de servicios que contribuyen a la economía con bajas emisiones de carbono y a la resistencia al cambio climático (incluyendo el apoyo a dichos servicios)","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=1192","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":1192,"source_updated":"2025-05-29"}],"match_method":"","feder_cost_reconciled_to_grant":null,"scope_note":"El coste de la operación FEDER no es la inversión subvencionable del proyecto. Las actuaciones de otros años son antecedentes de la empresa, no el proyecto de esta solicitud.","identity_sources":[],"fields":{"nif":"","project_description":"","municipality":"","province":"","project_start_dates":"","project_end_dates":""}},"province":null},{"import_key":"011197d43d6b92293928f2f0","enrichment":{"version":1,"reviewed_at":"2026-11-20","project_operations":[],"related_company_operations":[],"match_method":"","feder_cost_reconciled_to_grant":null,"scope_note":"El coste de la operación FEDER no es la inversión subvencionable del proyecto. Las actuaciones de otros años son antecedentes de la emp